// Some portions generated by Co-Pilot
import React from "react";
import { render, screen, fireEvent, cleanup } from "@testing-library/react";
import { describe, it, expect, vi, afterEach } from "vitest";
import AllReleaseCard from "../index";
import type { MarketplaceRelease } from "@/hooks";
import { axe } from "vitest-axe";
import { sendDownloadEvent } from "@/utils/gtag";

vi.mock("next-intl", () => ({
  useLocale: () => "en",
  useTranslations: () => (key: string, values?: { count: number }) => {
    if (key === "Marketplace.Releases.empty-title")
      return "No distributions found";
    if (key === "Marketplace.Releases.reset-filters") return "Reset filters";
    if (key === "Marketplace.Releases.view-checksum") return "View checksum";
    if (key === "Marketplace.Releases.download") return "Download";
    if (key === "Marketplace.Releases.result-count")
      return `${values?.count} distributions`;
    return key;
  },
}));

vi.mock("@/i18n/navigation", () => ({
  Link: ({
    children,
    href,
    onClick,
    ...props
  }: {
    children: React.ReactNode;
    href: string | { pathname: string; query: Record<string, string> };
    onClick?: React.MouseEventHandler<HTMLAnchorElement>;
  }) => (
    <a
      {...props}
      href={
        typeof href === "string"
          ? href
          : `${href.pathname}?${new URLSearchParams(href.query)}`
      }
      onClick={(event) => {
        event.preventDefault();
        onClick?.(event);
      }}
    >
      {children}
    </a>
  ),
}));

vi.mock("@/components/Download/ChecksumModal", () => ({
  default: ({
    open,
    setOpen,
  }: {
    open: boolean;
    setOpen: (v: boolean) => void;
  }) =>
    open ? (
      <div data-testid="checksum-modal">
        <button onClick={() => setOpen(false)}>Close</button>
      </div>
    ) : null,
}));

vi.mock("@/components/Common/AnimatedPlaceholder", () => ({
  default: ({ children }: { children: React.ReactNode }) => (
    <div>{children}</div>
  ),
}));

vi.mock("@/hooks", () => ({
  getImageForDistribution: () => "/images/test-vendor.png",
}));

vi.mock("@/utils/gtag", () => ({
  sendDownloadEvent: vi.fn(),
}));

vi.mock("@/utils/fetchExtension", () => ({
  fetchExtension: () => "tar.gz",
}));

const mockRelease: MarketplaceRelease = {
  release_name: "jdk-21.0.3+9",
  vendor: "adoptium",
  binary: {
    architecture: "x64",
    distribution: "temurin",
    image_type: "jdk",
    jvm_impl: "hotspot",
    os: "linux",
    scm_ref: "abc123",
    openjdk_scm_ref: "def456",
    timestamp: "2024-04-01T00:00:00Z",
    aqavit_results_link: "https://example.com/aqavit-results",
    package: {
      link: "https://example.com/download.tar.gz",
      name: "OpenJDK21U-jdk_x64_linux.tar.gz",
      sha256sum: "sha256abc123",
      sha256sum_link: "https://example.com/sha256",
      signature_link: "https://example.com/sig",
    },
  },
};

describe("AllReleaseCard", () => {
  afterEach(() => {
    cleanup();
  });

  it("renders loading state when results is null", () => {
    const { container } = render(<AllReleaseCard results={null} />);
    expect(container.firstChild).not.toBeNull();
    expect(screen.getByTestId("marketplace-loading")).toBeInTheDocument();
    expect(
      screen.queryByText("No distributions found"),
    ).not.toBeInTheDocument();
  });

  it("renders no results state when results is empty array", () => {
    const { getByText } = render(<AllReleaseCard results={[]} />);
    expect(getByText(/No distributions found/i)).toBeTruthy();
  });

  it("calls onReset when reset button is clicked in empty state", () => {
    const onReset = vi.fn();
    const { getByText } = render(
      <AllReleaseCard results={[]} onReset={onReset} />,
    );
    const resetButton = getByText(/Reset Filters/i);
    fireEvent.click(resetButton);
    expect(onReset).toHaveBeenCalledTimes(1);
  });

  it("does not show reset button in empty state when onReset is not provided", () => {
    const { queryByText } = render(<AllReleaseCard results={[]} />);
    expect(queryByText(/Reset Filters/i)).toBeNull();
  });

  it("renders release cards when results are provided", () => {
    const { container } = render(<AllReleaseCard results={[mockRelease]} />);
    expect(container.firstChild).not.toBeNull();
    // Release name should appear
    const releaseNameEls = container.querySelectorAll("h3");
    expect(releaseNameEls.length).toBeGreaterThan(0);
  });

  it("opens checksum modal when checksum button is clicked", () => {
    render(<AllReleaseCard results={[mockRelease]} />);
    const checksumButtons = screen.queryAllByLabelText("View checksum");
    expect(checksumButtons.length).toBeGreaterThan(0);
    fireEvent.click(checksumButtons[0]);
    expect(screen.getByTestId("checksum-modal")).toBeTruthy();
  });

  it("renders multiple releases", () => {
    const releases = [
      mockRelease,
      { ...mockRelease, release_name: "jdk-17.0.10+7" },
    ];
    const { container } = render(<AllReleaseCard results={releases} />);
    expect(
      container.querySelectorAll('[data-testid="marketplace-release"]'),
    ).toHaveLength(2);
  });

  it("uses one responsive card and one set of actions per result", () => {
    render(<AllReleaseCard results={[mockRelease]} />);
    expect(screen.getAllByRole("article")).toHaveLength(1);
    expect(
      screen.getAllByRole("heading", { name: mockRelease.release_name }),
    ).toHaveLength(1);
    expect(
      screen.getAllByRole("button", { name: "View checksum" }),
    ).toHaveLength(1);
    expect(screen.getAllByRole("link", { name: /Download/ })).toHaveLength(1);
  });

  it("preserves download URLs and tracking", () => {
    render(<AllReleaseCard results={[mockRelease]} />);
    const link = screen.getByRole("link", { name: /Download/ });
    expect(link).toHaveAttribute(
      "href",
      "/download?link=https%3A%2F%2Fexample.com%2Fdownload.tar.gz&vendor=Adoptium",
    );
    fireEvent.click(link);
    expect(sendDownloadEvent).toHaveBeenCalledWith({
      link: "https://example.com/download.tar.gz",
      os: "linux",
      arch: "x64",
      pkg_type: "jdk",
      version: mockRelease.release_name,
      vendor: "Adoptium",
    });
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<AllReleaseCard results={[mockRelease]} />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
